import torch


def gen_inputs(ctx, device):
    dtype = getattr(torch, ctx["inp2__dtype"])
    shape = ctx["inp2__shape"]
    inp2 = torch.randn(shape, dtype=dtype, device=device)
    inp2 = torch.where(inp2 == 0, torch.ones_like(inp2), inp2)
    return {"inp2": inp2}


def run_correctness(inp1, inp2):
    return torch.fmod(inp1.float(), inp2.float()).to(inp1.dtype)


def run(inp1, inp2):
    return torch.fmod(inp1, inp2)
